      "codigo_refatorado": "using System; using System.Collections.Generic; using UnityEngine; namespace PerformanceAdvisor.StressTest { public class StressTestScene : MonoBehaviour { public bool stressGc = false; public bool stressCpu = false; public bool stressDraw = false; public GameObject testPrefab; [Range(1, 20)] public float spawnRadius = 10f; [Range(1, 50)] public int cubesPerFrame = 1; public bool useUniqueMaterials = false; [Range(1, 512)] public int cpuScansPerFrame = 1; public int emptyObjects = 0; public int gcConcatIterations = 1000; public int gcArrayAllocs = 0; public int overdrawLayers = 0; public Material overdrawMaterial; [Range(0, 2000)] public int prepopulateCount = 0; private static readonly List<GameObject> CachedObjects = new List<GameObject>(2048); private MaterialPropertyBlock _propBlock; private static readonly int ColorPropertyId = Shader.PropertyToID(\"_Color\"); private void Awake() { _propBlock = new MaterialPropertyBlock(); } private void Start() { if (prepopulateCount > 0 && testPrefab != null) { for (int i = 0; i < prepopulateCount; i++) { SpawnOne(); } } for (int i = 0; i < emptyObjects; i++) { new GameObject(\"Empty_\" + i); } if (overdrawLayers > 0 && overdrawMaterial != null) { BuildOverdrawLayers(); } } private void BuildOverdrawLayers() { Camera cam = Camera.main; if (cam == null) return; float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad; for (int i = 0; i < overdrawLayers; i++) { float d = cam.nearClipPlane + 0.05f + i * 0.001f; float h = 2f * d * Mathf.Tan(halfFov) * 1.1f; var quad = GameObject.CreatePrimitive(PrimitiveType.Quad); Destroy(quad.GetComponent<Collider>()); quad.name = \"Overdraw_\" + i; quad.transform.SetParent(cam.transform, false); quad.transform.localPosition = new Vector3(0f, 0f, d); quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f); quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial; } } private void Update() { if (stressDraw && testPrefab != null) { int n = Mathf.Max(1, cubesPerFrame); for (int i = 0; i < n; i++) { SpawnOne(); } } } private void SpawnOne() { var clone = Instantiate(testPrefab, UnityEngine.Random.insideUnitSphere * spawnRadius, Quaternion.identity); if (useUniqueMaterials) { var rend = clone.GetComponent<Renderer>(); if (rend != null) { rend.GetPropertyBlock(_propBlock); _propBlock.SetColor(ColorPropertyId, new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value)); rend.SetPropertyBlock(_propBlock); } } } } }",
